-- 3D mannequin for every system exercise (apps/web/public/mannequin.js, Kova Health's own
-- parametric animation: 141 movement patterns, no external code or media). Each exercise gets one
-- animation entry with the inputs the mannequin classifies (an English movement slug, its muscle
-- and equipment vocabulary); about 20 were picked by hand where the automatic choice was wrong.
-- Replaces the 5 prototype `gym-mannequin:<name>` references. Generated.

update public.exercises set media = (select coalesce(jsonb_agg(m), '[]'::jsonb) from jsonb_array_elements(media) m where m->>'kind' <> 'animation') || $j$[{"kind": "animation", "ref": "kova-mannequin", "slug": "barbell-squat", "muscle": "quads", "equipment": "barbell", "category": ""}]$j$::jsonb where owner_id is null and slug = 'sentadilla';
